import java.io.*;import java.net.*;import java.nio.file.*;import java.util.concurrent.*;
public final class LongPoll730Check {
 static void ok(boolean b,String s){if(!b)throw new AssertionError(s);System.out.println("PASS: "+s);}
 static long waitFor(String base,String token,int room,long cursor)throws Exception{HttpURLConnection h=(HttpURLConnection)new URL(base+"/wait").openConnection();h.setRequestMethod("POST");h.setDoOutput(true);h.setReadTimeout(15000);h.setRequestProperty("Authorization","Bearer "+token);try{DataOutputStream out=new DataOutputStream(h.getOutputStream());out.writeInt(GunnyServer.MAGIC);out.writeInt(room);out.writeLong(cursor);out.close();if(h.getResponseCode()!=200)throw new IOException("HTTP "+h.getResponseCode());return new DataInputStream(h.getInputStream()).readLong();}finally{h.disconnect();}}
 public static void main(String[] args)throws Exception{CloudStore.Memory store=new CloudStore.Memory();store.register("wait@730.test","test-password-123","Wait");try(GunnyServer server=new GunnyServer(new InetSocketAddress("127.0.0.1",0),Path.of("backend/assets"),store)){ServerCheck.base="http://127.0.0.1:"+server.port();String token=Equipment718ServerCheck.login("wait@730.test");int id=Equipment718ServerCheck.call(token,"create",o->{o.writeByte(1);o.writeByte(0);o.writeByte(-1);}).readInt();var r=server.rooms.get(id);long cursor=waitFor(ServerCheck.base,token,id,Long.MIN_VALUE);ExecutorService pool=Executors.newSingleThreadExecutor();try{Future<Long> f=pool.submit(()->waitFor(ServerCheck.base,token,id,cursor));Thread.sleep(200);ok(!f.isDone(),"Unchanged room holds the request instead of immediately polling");long start=System.nanoTime();Equipment718ServerCheck.call(token,"profile",null);ok(TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-start)<1000,"An outstanding wait does not lock the session or block commands");Equipment718ServerCheck.call(token,"ready",o->o.writeBoolean(true));ok(f.get(2,TimeUnit.SECONDS)!=cursor,"Room event wakes the held request promptly");long next=server.longPoll.state(r);start=System.nanoTime();long same=waitFor(ServerCheck.base,token,id,next);long elapsed=TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-start);ok(same==next&&elapsed>=11000&&elapsed<14000,"Quiet room returns an unchanged heartbeat after twelve seconds");ok(server.longPoll.waiting.isEmpty(),"Completed waits release their per-session guard");}finally{pool.shutdownNow();}}System.out.println("All long polling 7.3.0 checks passed");}
}
